// Symptom: the admin label token renders at 8px instead of 10px.
// Checks the admin label on each signed-in screen where it may appear.
const routes = ['/ops/radar', '/ops/operations', '/ops/launchpad', '/ops/rules'];
for (const route of routes) {
  await page.goto(route);
  const adminLabel = page.getByRole('status', { name: 'Admin' });
  if (await adminLabel.count() === 0) continue;
  await expect(adminLabel.first()).toHaveCSS('font-size', '10px');
}
