const routes = ['/ops/radar', '/ops/operations', '/ops/launchpad', '/ops/rules'];
let found = 0;
for (const route of routes) {
  await page.goto(route);
  const label = page.getByText('Admin', { exact: true });
  if (await label.count() === 0) continue;
  found++;
  await expect(label.first()).toHaveCSS('font-size', '10px');
}
if (found === 0) throw new Error('admin label not found on any signed-in route');
